export const QUIZ_ITEMS = [
  { id: "1665", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام ابن تيمية؟ وما أبرز مؤلفاته؟", answer: "هو شيخ الإسلام أحمد بن عبد الحليم بن تيمية الحراني الحنبلي (661-728هـ). وُلد في حرّان وعاش في دمشق. أبرز مؤلفاته: «درء تعارض العقل والنقل»، «منهاج السنة النبوية»، «الفتاوى الكبرى»، «الاستقامة»، «اقتضاء الصراط المستقيم». اشتُهر بالتجديد في مسائل العقيدة والرد على الفلسفة الكلامية وعلى الغلو والبدع.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1666", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما الفرق بين «الإسناد» و«المتن» في علم الحديث؟", answer: "الإسناد (السند): هو سلسلة الرواة الذين نقلوا الحديث من راوٍ إلى آخر حتى وصل إلى النبي ﷺ. والمتن: هو نص الحديث ومضمونه الذي قاله النبي ﷺ أو فعله. الحكم على الحديث صحةً وضعفاً يعتمد في الأساس على دراسة الإسناد (رجاله وعلله)، ثم دراسة المتن للكشف عن الشذوذ والنكارة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1667", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام النووي؟ وما أبرز مؤلفاته؟", answer: "هو الإمام يحيى بن شرف النووي الشافعي (631-676هـ)، من أكبر علماء الإسلام وأتقاهم. وُلد في نوى بسوريا. أبرز مؤلفاته: «رياض الصالحين» و«الأذكار» و«المنهاج في شرح صحيح مسلم» (المعروف بشرح النووي) و«المجموع شرح المهذب» و«الأربعون النووية». توفي وعمره 45 سنة لكنه ترك إرثاً علمياً ضخماً يُدرَّس حتى اليوم.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1668", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما المذاهب الفقهية الأربعة المعتمدة؟ ومن مؤسسوها؟", answer: "المذاهب الفقهية الأربعة: 1) الحنفي — مؤسسه الإمام أبو حنيفة النعمان (80-150هـ). 2) المالكي — مؤسسه الإمام مالك بن أنس (93-179هـ). 3) الشافعي — مؤسسه الإمام محمد بن إدريس الشافعي (150-204هـ). 4) الحنبلي — مؤسسه الإمام أحمد بن حنبل (164-241هـ). كل مذهب له منهجه في الاجتهاد والاستدلال، ويُعبّر عن فهم دقيق للنصوص الشرعية، والخلاف بينها رحمة وتوسعة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1669", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "سهل", question: "من هو الإمام البخاري وما اسمه الكامل؟", answer: "هو محمد بن إسماعيل البخاري (194-256هـ)، وُلد في بخارى بأوزبكستان. مؤلف أصح كتاب بعد كتاب الله وهو الجامع الصحيح المعروف بصحيح البخاري الذي يحتوي على 7563 حديثاً مكرراً، وهو إمام علماء الحديث.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1670", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "في أي قرن عاش الإمام الغزالي وما لقبه الشهير؟", answer: "عاش أبو حامد الغزالي (450-505هـ) في القرن الخامس الهجري. لقّبه العلماء بـ«حجة الإسلام» لعلمه الغزير ومواقفه الدفاعية عن الإسلام. وُلد في طوس بخراسان (إيران)، وأشهر كتبه إحياء علوم الدين.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1671", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "من هو ابن تيمية وأين وُلد وتوفي؟", answer: "هو أحمد بن عبد الحليم ابن تيمية الحراني (661-728هـ). وُلد في حران (جنوب تركيا) وتوفي في سجن دمشق. عالم حنبلي موسوعي في الفقه والعقيدة والتفسير. أشهر طلابه ابن قيم الجوزية، وأشهر كتبه الفتاوى الكبرى ومنهاج السنة.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1672", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "ما اسم الإمام الشافعي كاملاً وأين وُلد؟", answer: "هو محمد بن إدريس الشافعي القرشي (150-204هـ). وُلد في غزة (فلسطين) وتوفي في مصر. مؤسس المذهب الشافعي وصاحب كتاب الرسالة أول مصنَّف في أصول الفقه. حفظ القرآن في سن السابعة وحفظ الموطأ في سن العاشرة.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1673", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "من هو ابن حجر العسقلاني وما أهم مؤلفاته في الحديث؟", answer: "هو أحمد بن علي بن حجر العسقلاني (773-852هـ)، مصري الأصل من عسقلان. أمير المؤمنين في الحديث. أشهر مؤلفاته: فتح الباري شرح صحيح البخاري (13 مجلداً)، والإصابة في تمييز الصحابة، وتقريب التهذيب. استغرق فتح الباري منه 25 عاماً.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1674", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "ما مدينة الميلاد والوفاة لكلٍّ من الأئمة الأربعة؟", answer: "أبو حنيفة: وُلد في الكوفة وتوفي في بغداد. مالك بن أنس: وُلد وتوفي في المدينة المنورة. الشافعي: وُلد في غزة وتوفي في الفسطاط (القاهرة). أحمد بن حنبل: وُلد وتوفي في بغداد.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1675", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "من هو ابن قيم الجوزية وما علاقته بابن تيمية؟", answer: "هو محمد بن أبي بكر ابن قيّم الجوزية (691-751هـ)، من دمشق. لازم شيخه ابن تيمية نحو 17 عاماً وسجن معه في قلعة دمشق. أشهر كتبه: زاد المعاد، إغاثة اللهفان، مدارج السالكين. أتم كثيراً مما بدأه ابن تيمية.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1676", section: "الحديث", category: "المصطلح", level: "سهل", question: "ما الحديث الذي يُعدّ من جوامع كلمه ﷺ ويبدأ بـ (إنما الأعمال)؟", answer: "«إنما الأعمال بالنيات، وإنما لكل امرئ ما نوى» — رواه البخاري (1) ومسلم (1907) عن عمر بن الخطاب رضي الله عنه", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1677", section: "الحديث", category: "الكتب", level: "سهل", question: "ما الكتاب الذي يأتي في المرتبة الثانية بعد صحيح البخاري في الصحة؟", answer: "صحيح مسلم — وهو الثاني بعد صحيح البخاري في الصحة عند جمهور العلماء؛ وذهب أبو علي النيسابوري وبعض علماء المغرب إلى تفضيل صحيح مسلم، ومرادهم حسن السياق وجمع طرق الحديث في موضع واحد لا رجحان أصل الصحة", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1678", section: "الحديث", category: "الكتب", level: "متوسط", question: "ما الكتب الستة (الأصول الستة) في الحديث النبوي؟", answer: "صحيح البخاري، وصحيح مسلم، وسنن أبي داود، وجامع الترمذي، وسنن النسائي، وسنن ابن ماجه. وتسميتها «الصحاح الستة» تسامح شائع؛ فالحكم بالصحة على الإطلاق إنما هو للصحيحين، أما السنن الأربعة ففيها الصحيح والحسن والضعيف، ولهذا يسميها المحدثون «الكتب الستة» أو «الأصول الستة»", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1679", section: "الحديث", category: "الكتب", level: "متوسط", question: "من ألّف مسند الإمام أحمد؟", answer: "الإمام أحمد بن حنبل رحمه الله جمعه وانتقاه؛ ورواه عنه ابنه عبد الله وزاد فيه زيادات، ثم رواه عن عبد الله أبو بكر القطيعي وله فيه زيادات أيضًا — فليس كل ما في المطبوع من رواية الإمام أحمد نفسه", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1680", section: "الحديث", category: "الكتب", level: "متوسط", question: "ما الكتاب الأول المصنَّف في الحديث النبوي الجامع بين الفقه والحديث؟", answer: "الموطأ لمالك بن أنس — أول كتاب مصنَّف في الحديث النبوي جامع بين الفقه والرواية.", explanation: "يُستفاد منه في باب الكتب. يُستفاد منه في باب الكتب مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1681", section: "الحديث", category: "المصطلح", level: "متوسط", question: "ما الحديث القدسي؟", answer: "ما أضافه النبي ﷺ إلى ربه عز وجل مما أوحي إليه من غير القرآن، فيرويه عن ربه. وهل لفظه من الله أم المعنى من الله واللفظ من النبي ﷺ؟ مسألة خلافية بين أهل العلم والقولان مشهوران. ويفارق القرآنَ بأنه لا يُتعبَّد بتلاوته، ولا تصح به الصلاة، ولا يلزم فيه التواتر، وفيه الصحيح والضعيف", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1682", section: "الحديث", category: "الرواة", level: "متوسط", question: "من الصحابي الذي روى أكثر من أربعة آلاف حديث؟", answer: "أبو هريرة رضي الله عنه — الصحابي الذي روى أكثر من أربعة آلاف حديث عن النبي ﷺ.", explanation: "يُستفاد منه في باب الرواة. يُستفاد منه في باب الرواة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1683", section: "الحديث", category: "الرواة", level: "متوسط", question: "من أول من أمر بتدوين الحديث رسمياً من الخلفاء؟", answer: "عمر بن عبد العزيز رحمه الله؛ كتب إلى أبي بكر بن محمد بن حزم: «انظر ما كان من حديث رسول الله ﷺ فاكتبه، فإني خفت دروس العلم وذهاب العلماء» — علّقه البخاري في كتاب العلم. وأشهر من قام بالتدوين بأمره: محمد بن مسلم بن شهاب الزهري", explanation: "يُستفاد منه في باب الرواة. يُستفاد منه في باب الرواة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1684", section: "الحديث", category: "الأحاديث الجامعة", level: "متوسط", question: "ما الحديث الذي يُعدّ من جوامع كلمه ويبدأ بـ (من حسن إسلام المرء)؟", answer: "«من حسن إسلام المرء تركه ما لا يعنيه» — رواه الترمذي (2317) وابن ماجه، وهو الحديث الثاني عشر من الأربعين النووية، وحسّنه النووي", explanation: "يُستفاد منه في باب الأحاديث الجامعة. يُستفاد منه في باب الأحاديث الجامعة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1685", section: "الحديث", category: "الأحاديث الجامعة", level: "متوسط", question: "ما أثقل شيء في الميزان يوم القيامة كما جاء في الحديث؟", answer: "حسن الخلق؛ لقوله ﷺ: «ما من شيء أثقل في ميزان المؤمن يوم القيامة من خلق حسن» — رواه أبو داود (4799) والترمذي (2002) عن أبي الدرداء رضي الله عنه، وصححه الألباني", explanation: "يُستفاد منه في باب الأحاديث الجامعة. يُستفاد منه في باب الأحاديث الجامعة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1686", section: "الحديث", category: "الأحاديث الجامعة", level: "سهل", question: "أكمل الحديث: لا يؤمن أحدكم حتى يحب لأخيه...", answer: "«ما يحب لنفسه» — متفق عليه: البخاري (13) ومسلم (45) عن أنس بن مالك رضي الله عنه", explanation: "يُستفاد منه في باب الأحاديث الجامعة. يُستفاد منه في باب الأحاديث الجامعة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1687", section: "الحديث", category: "الأربعون النووية", level: "متوسط", question: "من جمع الأربعين النووية في الحديث النبوي؟", answer: "يحيى بن شرف النووي — الإمام الذي جمع الأربعين النووية في الحديث (ت 676هـ).", explanation: "يُستفاد منه في باب الأربعون النووية. يُستفاد منه في باب الأربعون النووية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1688", section: "الحديث", category: "الصحاح", level: "متوسط", question: "ما الكتب الستة في الحديث؟", answer: "صحيح البخاري، وصحيح مسلم، وسنن أبي داود، وجامع الترمذي، وسنن النسائي، وسنن ابن ماجه. وتسميتها «الصحاح الستة» تسامح شائع لا يصح اصطلاحاً؛ فالصحيح المحض منها الصحيحان، وأمّا السنن الأربعة ففيها الصحيح والحسن والضعيف. والسادس منها سنن ابن ماجه عند ابن طاهر المقدسي، وجعل بعضهم مكانه موطأ مالك", explanation: "يُستفاد منه في باب الصحاح. يُستفاد منه في باب الصحاح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1689", section: "الحديث", category: "المصطلح", level: "متوسط", question: "ما الحديث الحسن؟", answer: "ما اتصل سنده بنقل عدلٍ خفيفِ الضبط عن مثله إلى منتهاه، من غير شذوذ ولا علة؛ فهو كالصحيح في شروطه إلا أن راويه أخفُّ ضبطاً. وينقسم إلى حسن لذاته، وحسن لغيره وهو الضعيف الذي تعددت طرقه فجبر بعضها بعضاً", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1690", section: "الحديث", category: "المصطلح", level: "صعب", question: "ما الإسناد؟", answer: "سلسلة الرجال الموصِّلة إلى المتن؛ وقد ينتهي إلى النبي ﷺ فيكون الحديث مرفوعاً، أو إلى صحابي فيكون موقوفاً، أو إلى تابعي فيكون مقطوعاً. وبه تُعرف صحة الرواية من ضعفها؛ قال عبد الله بن المبارك: «الإسناد من الدين، ولولا الإسناد لقال من شاء ما شاء» (رواه مسلم في مقدمة صحيحه)", explanation: "يُستفاد منه في باب المصطلح. يُستفاد منه في باب المصطلح مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1691", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما تعريف الحديث الصحيح؟", answer: "ما اتصل سنده بنقل العدل الضابط عن مثله إلى منتهاه، وسلم من الشذوذ والعلة", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1692", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما تعريف الحديث الحسن وكيف يختلف عن الصحيح؟", answer: "الحسن ما اتصل سنده ورواته عدول لكن خفيف الضبط، وهو دون الصحيح في المرتبة ويُحتج به", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1693", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما الحديث الضعيف وما حكم العمل به؟", answer: "ما فقد شرطاً فأكثر من شروط القبول (الصحيح أو الحسن). ومنهج هذا الموقع: لا يُعمل بالضعيف في الأحكام ولا العقائد ولا الترغيب ولا التعبّد؛ والخلاف التاريخي في فضائل الأعمال يُذكر للعلم مع ترجيح الترك والاستغناء بالصحيح والحسن", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1694", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما معنى الإسناد في علم الحديث؟", answer: "سلسلة الرواة الذين نقلوا الحديث من الصحابي إلى المصنِّف، ويُسمى أيضاً السند", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1695", section: "الحديث", category: "مصطلح الحديث", level: "صعب", question: "ما الحديث المتواتر وما حكمه؟", answer: "ما رواه جمع كثير يستحيل عادةً تواطؤهم على الكذب في كل طبقة، وهو يُفيد العلم القطعي", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1696", section: "الحديث", category: "مصطلح الحديث", level: "صعب", question: "ما الحديث القدسي وكيف يختلف عن القرآن الكريم؟", answer: "الحديث القدسي ما نسبه النبي ﷺ إلى ربه، ويختلف عن القرآن بأن القرآن معجز ومتعبَّد بتلاوته بخلاف القدسي", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1697", section: "الحديث", category: "حديث جبريل", level: "متوسط", question: "ما حديث جبريل المشهور وما أهميته؟", answer: "الحديث الذي سأل فيه جبريل النبيَّ ﷺ عن الإسلام والإيمان والإحسان وأشراط الساعة، وهو أصل جامع لعلوم الدين", explanation: "يُستفاد منه في باب حديث جبريل. يُستفاد منه في باب حديث جبريل مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1698", section: "الحديث", category: "الأحاديث الجامعة", level: "سهل", question: "ما معنى حديث: الدين النصيحة؟", answer: "النصيحة هنا بمعنى الإخلاص والصدق، أي أن الدين قائم على الإخلاص لله ولكتابه ولرسوله وللمسلمين عامة وخاصة", explanation: "يُستفاد منه في باب الأحاديث الجامعة. يُستفاد منه في باب الأحاديث الجامعة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1699", section: "الحديث", category: "صحيح البخاري", level: "سهل", question: "ما أول حديث في صحيح البخاري؟", answer: "حديث: إنما الأعمال بالنيات — رواه عمر بن الخطاب رضي الله عنه", explanation: "يُستفاد منه في باب صحيح البخاري. يُستفاد منه في باب صحيح البخاري مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1700", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما تعريف الحديث المتواتر؟", answer: "ما رواه جمع كثير يستحيل تواطؤهم على الكذب في كل طبقة من طبقات السند. وهو يفيد العلم اليقيني القطعي", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1701", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما الحديث الآحاد وما حكمه؟", answer: "ما لم يبلغ حد التواتر. وينقسم إلى: مشهور وعزيز وغريب. يفيد الظن الراجح ويجب العمل به في الأحكام الشرعية عند الصحة", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1702", section: "الحديث", category: "علم الرجال", level: "صعب", question: "ما الجرح والتعديل في علم الحديث؟", answer: "التعديل: توثيق الراوي بأنه ضابط عدل مقبول الرواية. الجرح: بيان ما يخل بعدالة الراوي أو ضبطه. وهو ميزان نقد المحدثين للرواة", explanation: "يُستفاد منه في باب علم الرجال. يُستفاد منه في باب علم الرجال مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1703", section: "الحديث", category: "كتب السنة", level: "سهل", question: "ما أصح كتاب بعد القرآن الكريم؟", answer: "صحيح البخاري (الجامع الصحيح) عند جمهور العلماء، ثم صحيح مسلم. وهما المعروفان بـ (الصحيحين)", explanation: "يُستفاد منه في باب كتب السنة. يُستفاد منه في باب كتب السنة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1704", section: "الحديث", category: "السنة النبوية", level: "متوسط", question: "ما الفرق بين السنة القولية والفعلية والتقريرية؟", answer: "القولية: ما قاله النبي ﷺ. الفعلية: ما فعله. التقريرية: ما سكت عنه وأقره ولم ينكره. والجميع حجة شرعية", explanation: "يُستفاد منه في باب السنة النبوية. يُستفاد منه في باب السنة النبوية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1705", section: "الحديث", category: "الأربعون النووية", level: "متوسط", question: "ما أول أحاديث الأربعين النووية وما معناه؟", answer: "إنما الأعمال بالنيات — معناه أن صحة الأعمال وقبولها مرتبط بالنية الخالصة لله تعالى.", explanation: "يُستفاد منه في باب الأربعون النووية. يُستفاد منه في باب الأربعون النووية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1706", section: "الحديث", category: "الأربعون النووية", level: "متوسط", question: "ما الحديث الثاني في الأربعين النووية؟", answer: "حديث جبريل — سأل جبريل النبي ﷺ عن الإسلام والإيمان والإحسان، فأجابه النبي. وهو حديث عمر بن الخطاب رضي الله عنه.", explanation: "يُستفاد منه في باب الأربعون النووية. يُستفاد منه في باب الأربعون النووية مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1707", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما الفرق بين الحديث المسند والحديث المرسل؟", answer: "المسند: ما اتصل سنده من راويه إلى النبي ﷺ دون انقطاع. المرسل: ما سقط من سنده الصحابي، فيُروى من التابعي مباشرةً إلى النبي ﷺ دون ذكر الصحابي.", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1708", section: "الحديث", category: "مصطلح الحديث", level: "صعب", question: "ما الفرق بين الحديث المرسَل والحديث المنقطع؟", answer: "المرسَل: ما سقط منه الصحابي فقط، إذ يرويه التابعي مباشرة عن النبي ﷺ. المنقطع: ما سقط من إسناده راوٍ واحد في أي موضع غير الصحابي، أو اثنان غير متواليين. كلاهما من أقسام الحديث الضعيف.", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1709", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما الفرق بين الحديث المرفوع والموقوف والمقطوع؟", answer: "المرفوع: ما أُسند إلى النبي ﷺ قولاً أو فعلاً أو تقريراً. الموقوف: ما أُسند إلى الصحابي ولم يرفعه إلى النبي. المقطوع: ما أُسند إلى التابعي.", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1710", section: "الحديث", category: "مصطلح الحديث", level: "متوسط", question: "ما الفرق بين الحديث المتواتر والآحاد؟ وما حجية كل منهما؟", answer: "المتواتر: ما رواه جمع عن جمع يستحيل تواطؤهم على الكذب من أول السند إلى آخره، ويفيد العلم القطعي. الآحاد: ما لم يبلغ حد التواتر، ويفيد الظن الغالب، ويُحتج به في العقيدة والأحكام عند جمهور العلماء. ولا تصح العبادة ولا الحكم إلا بمعرفة درجة الحديث.", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1711", section: "الحديث", category: "رجال الحديث", level: "متوسط", question: "من هم المكثرون من الصحابة رضي الله عنهم في رواية الحديث؟", answer: "المكثرون الستة: 1- أبو هريرة (5374 حديثاً). 2- عبد الله بن عمر (2630). 3- أنس بن مالك (2286). 4- عائشة أم المؤمنين (2210). 5- عبد الله بن عباس (1660). 6- جابر بن عبد الله (1540). ويأتي أبو هريرة في المرتبة الأولى لكثرة ملازمته للنبي ﷺ وصدق حفظه.", explanation: "يُستفاد منه في باب رجال الحديث. يُستفاد منه في باب رجال الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1712", section: "الحديث", category: "كتب الحديث", level: "سهل", question: "ما أصح الكتب بعد كتاب الله؟ وما الكتب الستة في الحديث؟", answer: "أصح الكتب بعد القرآن: صحيح البخاري ثم صحيح مسلم بإجماع أهل العلم. والكتب الستة (الصحاح الستة): البخاري، ومسلم، وسنن أبي داود، والترمذي، والنسائي، وابن ماجه. وعند بعضهم تُبدَّل ابن ماجه بموطأ الإمام مالك.", explanation: "يُستفاد منه في باب كتب الحديث. يُستفاد منه في باب كتب الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1713", section: "الحديث", category: "مصطلح الحديث", level: "صعب", question: "ما علم الجرح والتعديل؟ ولماذا نشأ؟", answer: "علم الجرح والتعديل: علم يُبحث فيه عن رواة الحديث من حيث القبول والرد. الجرح: بيان ما في الراوي من ضعف يوجب رد روايته. التعديل: توثيق الراوي وقبول حديثه. نشأ لصون السنة النبوية من الوضع والكذب والتدليس، ويُعد ابن معين والبخاري والنسائي من أبرز أئمته.", explanation: "يُستفاد منه في باب مصطلح الحديث. يُستفاد منه في باب مصطلح الحديث مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1714", section: "الحديث", category: "أحاديث مشهورة", level: "سهل", question: "ما الحديث الأول الذي يُفتتح به صحيح البخاري؟ وما مناسبته؟", answer: "«إنما الأعمال بالنيات وإنما لكل امرئ ما نوى» (البخاري). اختاره البخاري ليُنبه أن العمل لا يُقبل إلا بالنية الخالصة لله. وهذا الحديث يُعد ثُلث العلم عند كثير من الأئمة كالشافعي وأبي داود وابن مهدي.", explanation: "يُستفاد منه في باب أحاديث مشهورة. يُستفاد منه في باب أحاديث مشهورة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" }
];

