export const FAWAID_ITEMS = [
  { text: "لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه؛ فالإيثار من تمام الإيمان، وهذا من مكارم الأخلاق التي أمر بها الشرع في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "المؤمن للمؤمن كالبنيان يشد بعضه بعضاً؛ فالتعاون بين المسلمين من أصول الإسلام، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من كان في حاجة أخيه كان الله في حاجته؛ فنصرة المسلم واجبة، وهذا من آداب الإسلام التي تُجمّل المسلم وتُقربه من ربه في معاملة إخوانه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "الكلمة الطيبة صدقة؛ فحسن الكلام من أعظم أبواب الخير، وهذا من مكارم الأخلاق التي أمر بها الشرع في الدنيا والآخرة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من أحسن وضوءه أحسن صلاته؛ فالطهارة مفتاح قبول الصلاة، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "رواه أبو داود — حسنه الألباني", author_name: "سنن أبي داود" },
  { text: "من حسن إسلام المرء تركه ما لا يعنيه؛ فترك ما لا يعنيه من أعظم موفّرات الوقت والطاقة والعلاقات. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "رواه الترمذي (2317) — حسنه الألباني", author_name: "سنن الترمذي" },
  { text: "الدنيا سجن المؤمن وجنة الكافر؛ فمن عرف قدر الآخرة قلّ اهتمامه بالدنيا وزاد عمله لما بعد الموت. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "رواه مسلم (2956)", author_name: "صحيح مسلم" },
  { text: "من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره؛ فحسن الجوار من أعظم أسباب تمام الإيمان وصلاح المجتمع. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "إن الله يحب التواضع ويكره الكبر؛ فالتواضع يرفع صاحبه والكبر يحطّه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..........................", category: "الأخلاق", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "الصبر نصف الإيمان؛ فمن صبر على البلاء نال الأجر، ومن جزع فقد خيراً كثيراً. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..................", category: "العقيدة", source: "رواه أبو نعيم في الحلية", author_name: "حلية الأولياء" },
  { text: "من سلك طريقاً يلتمس فيه علماً سهّل الله له به طريقاً إلى الجنة؛ فطلب العلم عبادة وطريق نجاة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "خيركم من تعلّم القرآن وعلّمه؛ فالتعامل مع كتاب الله يستوجب تدبره وحفظه ونشره بين الناس. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.....", category: "القرآن", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "من أحب لقاء الله أحب الله لقاءه؛ فمحبة الله تظهر في محبة لقائه يوم القيامة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.................", category: "العقيدة", source: "رواه البخاري (6509)", author_name: "صحيح البخاري" },
  { text: "الدعاء هو العبادة؛ فمن أكثر من الدعاء تقرّب إلى الله ونال الإجابة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..........................", category: "الآداب", source: "رواه الترمذي (3372) — حسنه الألباني", author_name: "سنن الترمذي" },
  { text: "من صلى عليّ صلاة صلى الله عليه بها عشراً؛ فالصلاة على النبي ﷺ من أعظم القربات. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..............", category: "الحديث", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه؛ فالإيثار من تمام الإيمان. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.........................", category: "الأخلاق", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "المؤمن للمؤمن كالبنيان يشد بعضه بعضاً؛ فالتعاون بين المسلمين من أصول الإسلام. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة...............", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من كان في حاجة أخيه كان الله في حاجته؛ فنصرة المسلم واجبة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..................................", category: "الآداب", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "الكلمة الطيبة صدقة؛ فحسن الكلام من أعظم أبواب الخير. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة........................................", category: "الأخلاق", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "من أحسن وضوءه أحسن صلاته؛ فالطهارة مفتاح قبول الصلاة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.......................................", category: "الفقه", source: "رواه أبو داود — حسنه الألباني", author_name: "سنن أبي داود" },
  { text: "من حسن إسلام المرء تركه ما لا يعنيه؛ فترك ما لا يعنيه من أعظم موفّرات الوقت والطاقة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة........", category: "الآداب", source: "رواه الترمذي (2317) — حسنه الألباني", author_name: "سنن الترمذي" },
  { text: "الدنيا سجن المؤمن وجنة الكافر؛ فمن عرف قدر الآخرة قلّ اهتمامه بالدنيا. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة......................", category: "العقيدة", source: "رواه مسلم (2956)", author_name: "صحيح مسلم" },
  { text: "من كان يؤمن بالله واليوم الآخر فليحسن إلى جاره؛ فحسن الجوار من تمام الإيمان. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة................", category: "الآداب", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "خيركم من تعلّم القرآن وعلّمه؛ فالتعامل مع كتاب الله يستوجب تدبره وحفظه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.....................", category: "القرآن", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "من صلى عليّ صلاة صلى الله عليه بها عشراً؛ فالصلاة على النبي ﷺ من أعظم القربات. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة..............", category: "الحديث", source: "رواه مسلم", author_name: "صحيح مسلم" }
];
